      # Sends Ticket Replied: the plan's `server: true` event.
      def ticket_replied(
          request:,
          user_id:,
          message_id:,
          ticket_id:,
          timestamp: nil
      )
        deliver(request, "Ticket Replied", user_id, message_id, timestamp, { "ticket_id" => ticket_id })
      end


      # Sends `Experiment Viewed` for a visitor's assignment (`TorqueLift::Flags` calls this; the
      # app does not). The message id is the experiment, the unit and the variation, so a repeat
      # is dropped.
      def experiment_viewed(request:, user_id:, experiment_id:, variation_id:, flag_key:, unit:)
