          request, "Experiment Viewed", user_id,
          "experiment-viewed-#{experiment_id}-#{unit}-#{variation_id}", nil,
          { "experiment_id" => experiment_id, "variation_id" => variation_id, "flag_key" => flag_key },
          anonymous_ok: true
