      end

      def read_anonymous_id(request)
        cookies = request.respond_to?(:cookies) ? request.cookies : nil
        value = cookies.respond_to?(:[]) ? cookies[COOKIE] : nil
        value.is_a?(String) && !value.empty? && value.length <= 128 ? value : nil
      rescue StandardError
        nil
      end

      def background(&block)
        Thread.new do
          Thread.current.report_on_exception = false
          block.call
        end
        nil
      end

      def post(url, key, body, event)
        uri = URI.parse(url)
        http = Net::HTTP.new(uri.host, uri.port)
        http.use_ssl = uri.scheme == "https"
        http.open_timeout = TIMEOUT_SECONDS
        http.read_timeout = TIMEOUT_SECONDS
        post = Net::HTTP::Post.new(uri.request_uri, "Content-Type" => "application/json", "X-Write-Key" => key)
        post.body = JSON.generate(body)
        status = http.request(post).code.to_i
        log_warning("[torque] the collector answered #{status} for #{event}") if status >= 400
      rescue StandardError => e # the caller's response must never fail on analytics
        log_warning("[torque] could not send #{event}: #{e.class.name}")
      end

      def deliver(request, event, user_id, message_id, timestamp, properties, anonymous_ok: false)
