          "type" => "track",
          "event" => event,
          "messageId" => message_id.to_s,
          "timestamp" => timestamp || Time.now.utc.iso8601,
          "properties" => properties.reject { |_name, value| value.nil? }.merge(TorqueLift::GLOBAL_PROPERTIES),
          "context" => TorqueLift::GLOBAL_CONTEXT.merge("library" => { "name" => "torque-server", "version" => "1" })
        }
        body["userId"] = user_id.to_s unless user_id.to_s.empty?
        body["anonymousId"] = anonymous_id if anonymous_id
